import 'package:charcoal_ui/charcoal_ui.dart';
import 'package:flutter/widgets.dart';

/// A responsive pair of primary and secondary actions.
final class AgentButtonExample extends StatelessWidget {
  const AgentButtonExample({
    required this.onContinue,
    required this.onCancel,
    super.key,
  });

  final VoidCallback onContinue;
  final VoidCallback onCancel;

  @override
  Widget build(BuildContext context) {
    final gap = CharcoalTheme.of(context).dimensions.space.component20;
    return LayoutBuilder(
      builder: (context, constraints) {
        final compact = constraints.maxWidth < 420;
        final cancel = CharcoalButton(
          fullWidth: compact,
          onPressed: onCancel,
          child: const Text('Cancel'),
        );
        final submit = CharcoalButton(
          fullWidth: compact,
          onPressed: onContinue,
          variant: CharcoalButtonVariant.primary,
          child: const Text('Continue'),
        );
        if (compact) {
          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            mainAxisSize: MainAxisSize.min,
            children: <Widget>[
              submit,
              SizedBox(height: gap),
              cancel,
            ],
          );
        }
        return Row(
          mainAxisSize: MainAxisSize.min,
          children: <Widget>[
            cancel,
            SizedBox(width: gap),
            submit,
          ],
        );
      },
    );
  }
}

import 'package:charcoal_ui/charcoal_ui.dart';
import 'package:flutter/widgets.dart';

/// Opens the same modal task as a dialog or bottom sheet based on available width.
final class AgentModalExample extends StatelessWidget {
  const AgentModalExample({super.key});

  @override
  Widget build(BuildContext context) {
    return CharcoalButton(
      onPressed: () => _openModal(context),
      variant: CharcoalButtonVariant.primary,
      child: const Text('Review changes'),
    );
  }

  Future<void> _openModal(BuildContext context) async {
    final compact = MediaQuery.sizeOf(context).width < 600;
    await showCharcoalModal<void>(
      actions: <Widget>[
        CharcoalButton(
          onPressed: () => Navigator.of(context).pop(),
          variant: CharcoalButtonVariant.primary,
          child: const Text('Done'),
        ),
      ],
      child: const CharcoalTypography(
        child: Text(
          'Your profile and visibility changes are ready to publish.',
        ),
      ),
      context: context,
      style: compact
          ? CharcoalModalStyle.bottomSheet
          : CharcoalModalStyle.center,
      title: 'Review changes',
    );
  }
}

import 'package:charcoal_ui/charcoal_ui.dart';
import 'package:flutter/widgets.dart';

enum _Visibility { everyone, followers, private }

/// A parent-owned single selection with descriptive options.
final class AgentDropdownExample extends StatefulWidget {
  const AgentDropdownExample({super.key});

  @override
  State<AgentDropdownExample> createState() => _AgentDropdownExampleState();
}

final class _AgentDropdownExampleState extends State<AgentDropdownExample> {
  _Visibility? _value = _Visibility.everyone;

  static const _options = <CharcoalDropdownOption<_Visibility>>[
    CharcoalDropdownOption(
      value: _Visibility.everyone,
      label: 'Everyone',
      secondary: 'Visible to anyone',
    ),
    CharcoalDropdownOption(
      value: _Visibility.followers,
      label: 'Followers',
      secondary: 'Visible to your followers',
    ),
    CharcoalDropdownOption(
      value: _Visibility.private,
      label: 'Only me',
      secondary: 'Keep this private',
    ),
  ];

  @override
  Widget build(BuildContext context) {
    return CharcoalDropdown<_Visibility>(
      label: 'Visibility',
      onChanged: (value) => setState(() => _value = value),
      options: _options,
      showLabel: true,
      value: _value,
    );
  }
}

import 'package:charcoal_ui/charcoal_ui.dart';
import 'package:flutter/widgets.dart';

enum _FeedMode { recent, popular, saved }

/// A responsive, parent-owned view switcher.
final class AgentSegmentedControlExample extends StatefulWidget {
  const AgentSegmentedControlExample({super.key});

  @override
  State<AgentSegmentedControlExample> createState() =>
      _AgentSegmentedControlExampleState();
}

final class _AgentSegmentedControlExampleState
    extends State<AgentSegmentedControlExample> {
  _FeedMode _value = _FeedMode.recent;

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(
      builder: (context, constraints) => CharcoalSegmentedControl<_FeedMode>(
        fullWidth: constraints.maxWidth < 480,
        onChanged: (value) => setState(() => _value = value),
        segments: const <CharcoalSegment<_FeedMode>>[
          CharcoalSegment(value: _FeedMode.recent, child: Text('Recent')),
          CharcoalSegment(value: _FeedMode.popular, child: Text('Popular')),
          CharcoalSegment(value: _FeedMode.saved, child: Text('Saved')),
        ],
        semanticLabel: 'Feed order',
        value: _value,
      ),
    );
  }
}

import 'package:charcoal_ui/charcoal_ui.dart';
import 'package:flutter/widgets.dart';

/// Launches transient feedback from a context that owns an Overlay.
final class AgentFeedbackExample extends StatelessWidget {
  const AgentFeedbackExample({super.key});

  @override
  Widget build(BuildContext context) {
    final gap = CharcoalTheme.of(context).dimensions.space.component20;
    return Wrap(
      spacing: gap,
      runSpacing: gap,
      children: <Widget>[
        CharcoalButton(
          onPressed: () =>
              showCharcoalToast(context: context, message: 'Changes saved'),
          child: const Text('Show toast'),
        ),
        CharcoalButton(
          onPressed: () =>
              showCharcoalSnackBar(context: context, message: 'Draft restored'),
          child: const Text('Show snackbar'),
        ),
      ],
    );
  }
}

import 'package:charcoal_ui/charcoal_ui.dart';
import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';

/// A controlled field that exposes validation without replacing Charcoal internals.
final class AgentTextFieldExample extends StatefulWidget {
  const AgentTextFieldExample({super.key});

  @override
  State<AgentTextFieldExample> createState() => _AgentTextFieldExampleState();
}

final class _AgentTextFieldExampleState extends State<AgentTextFieldExample> {
  String _value = '';

  @override
  Widget build(BuildContext context) {
    final invalid = _value.isNotEmpty && _value.length < 3;
    return CharcoalTextField(
      assistiveText: invalid
          ? 'Use at least 3 characters.'
          : 'This appears on your profile.',
      invalid: invalid,
      label: 'Display name',
      onChanged: (value) => setState(() => _value = value),
      placeholder: 'Enter a name',
      required: true,
      showLabel: true,
      textInputAction: TextInputAction.done,
    );
  }
}

